-- Hero + offer copy
INSERT OR REPLACE INTO settings (key, value, category) VALUES
  ('hero_headline', 'সাদা স্রাব সমস্যার ১০০% প্রাকৃতিক ও কার্যকরী সমাধান', 'content'),
  ('hero_subheadline', 'জার্মান ফর্মুলায় তৈরি, BCSIR পরীক্ষিত হারবাল সাপ্লিমেন্ট — ২/৩ সপ্তাহ নিয়মিত সেবনে সাদা স্রাব সমস্যার প্রাকৃতিক সমাধান। কোনো পার্শ্বপ্রতিক্রিয়া নেই। সারা বাংলাদেশে ক্যাশ অন ডেলিভারি — পণ্য হাতে পেয়ে টাকা দিন।', 'content'),
  ('offer_title', 'বিশেষ ডিসকাউন্ট অফার চলছে!', 'content'),
  ('offer_description', 'আজকে অর্ডার করলে ২ মাসের কোর্সে ডেলিভারি চার্জ সম্পূর্ণ ফ্রি! স্টক খুবই সীমিত — দেরি করলেই মিস!', 'content'),
  ('seo_title', 'Nature Care Bangladesh — সাদা স্রাব সমস্যার প্রাকৃতিক সমাধান | ক্যাশ অন ডেলিভারি', 'seo'),
  ('seo_description', 'সাদা স্রাব ও লিউকোরিয়া সমস্যার ১০০% প্রাকৃতিক হারবাল সমাধান। BCSIR পরীক্ষিত, কোনো পার্শ্বপ্রতিক্রিয়া নেই। সারা বাংলাদেশে ক্যাশ অন ডেলিভারি।', 'seo'),
  ('seo_keywords', 'সাদা স্রাব, লিউকোরিয়া, নারী স্বাস্থ্য, হারবাল সাপ্লিমেন্ট, nature care bangladesh, ক্যাশ অন ডেলিভারি', 'seo'),
  ('fb_share_title', 'সাদা স্রাব সমস্যার ১০০% প্রাকৃতিক সমাধান — Nature Care Bangladesh', 'seo'),
  ('fb_share_description', 'BCSIR পরীক্ষিত হারবাল সাপ্লিমেন্ট। ক্যাশ অন ডেলিভারি — এখনই অর্ডার করুন!', 'seo');

-- Product (id=1) rewritten
UPDATE products SET
  name = 'ন্যাচার কেয়ার লিউকো কেয়ার',
  subtitle = 'নারীদের সাদা স্রাব ও লিউকোরিয়া সমস্যার প্রাকৃতিক হারবাল সমাধান',
  slug = 'leuko-care',
  description = 'অতিরিক্ত সাদা স্রাব, দুর্গন্ধ, চুলকানি কিংবা জ্বালাপোড়া — এই সমস্যাগুলো নিয়ে দিনের পর দিন নীরবে কষ্ট পাচ্ছেন? ন্যাচার কেয়ার লিউকো কেয়ার তৈরি হয়েছে সম্পূর্ণ প্রাকৃতিক হারবাল উপাদানে, জার্মান ফর্মুলা অনুসরণ করে। ইতিমধ্যে হাজারো মা-বোন এই সাপ্লিমেন্ট ব্যবহার করে উপকৃত হয়েছেন। ২/৩ সপ্তাহ নিয়মিত সেবনে সাদা স্রাব সমস্যার প্রাকৃতিক সমাধান পাবেন ইনশাআল্লাহ — মা হওয়ার স্বপ্ন থেমে থাকবে না, আমরা আছি আপনার পাশে।',
  features = '["জার্মান ফর্মুলায় তৈরি ও BCSIR পরীক্ষিত","১০০% প্রাকৃতিক, নিরাপদ ও হালাল উপাদান","কোনো পার্শ্বপ্রতিক্রিয়া নেই","৭ দিনের মধ্যে কার্যকরী পরিবর্তন অনুভব করবেন","গোপনীয়তা ১০০% রক্ষা করা হয় — সাদামাটা প্যাকেজিং","অগ্রীম পেমেন্ট ছাড়াই অর্ডার — ক্যাশ অন ডেলিভারি"]',
  benefits = '["অতিরিক্ত সাদা স্রাব স্থায়ীভাবে সমাধানে সাহায্য করে","সাদা স্রাবের দুর্গন্ধ, চুলকানি ও জ্বালাপোড়া দূর করে","পিরিয়ডকালীন তীব্র পেট ব্যথা, পিঠে ব্যথা ও মাথা ব্যথা কমায়","অনিয়মিত বা অতিরিক্ত মাসিক সমস্যার সমাধানে কার্যকরী","প্রস্রাবে ব্যথা বা জ্বালাপোড়া কমাতে সাহায্য করে","মাথা ঘোরানো, হাত-পা জ্বালাপোড়া দূর করে","সাদা স্রাবের কারণে শরীর দুর্বল ও শুকিয়ে যাওয়ার সমস্যা দূর করে","জরায়ু দুর্বলতা কাটিয়ে ভেতর থেকে শক্তি ও স্বাচ্ছন্দ্য ফিরিয়ে আনে","দাম্পত্য জীবনে আগ্রহ ফিরিয়ে আনতে সাহায্য করে","খাবারে অরুচির সমস্যা কমাতে সহায়তা করে"]',
  ingredients = 'অশোক ছাল, লোধ্র, শতমূলী (শতাবরী), অশ্বগন্ধা, আমলকী, যষ্টিমধুসহ সম্পূর্ণ প্রাকৃতিক হারবাল উপাদান — কোনো ক্ষতিকর কেমিক্যাল নেই',
  usage_instructions = 'প্রতিদিন সকালে ঘুম থেকে উঠে খালি পেটে ১টি এবং রাতে খাবারের ৩০ মিনিট পর ১টি করে ট্যাবলেট সেবন করুন। বি.দ্র: সেবনকালে ঠান্ডা পানি, অতিরিক্ত ঝাল-মিষ্টি ও তেলযুক্ত খাবার এড়িয়ে চলুন। গর্ভবতী অবস্থায় সেবনের আগে অবশ্যই ডাক্তারের পরামর্শ নিন।',
  package_details = '১ মাসের কোর্স — ৬০টি ট্যাবলেট',
  main_image = 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800&q=80',
  gallery_images = '["https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=800&q=80","https://images.unsplash.com/photo-1550572017-edd951b55104?w=800&q=80","https://images.unsplash.com/photo-1471864190281-a93a3070b6de?w=800&q=80","https://images.unsplash.com/photo-1512069772995-ec65ed45afd6?w=800&q=80"]',
  regular_price = 1390,
  sale_price = 990
WHERE id = 1;

