-- Reviews (women-centric)
DELETE FROM reviews;
INSERT INTO reviews (customer_name, review_text, rating, is_published, is_featured, sort_order) VALUES
  ('শারমিন আক্তার, ঢাকা', 'অনেক বছর ধরে সাদা স্রাবের সমস্যায় ভুগছিলাম, লজ্জায় কাউকে বলতেও পারতাম না। ৩ সপ্তাহ সেবনের পর আলহামদুলিল্লাহ অনেক ভালো আছি। প্যাকেজিং দেখে কেউ বুঝতেও পারেনি ভেতরে কী।', 5, 1, 1, 1),
  ('নাসরিন বেগম, চট্টগ্রাম', 'পিরিয়ডের সময় তীব্র পেট ব্যথায় কষ্ট পেতাম। ১ মাসের কোর্স শেষ করার পর ব্যথা অনেক কমেছে। এখন ২য় মাসের কোর্স চালাচ্ছি। ধন্যবাদ Nature Care।', 5, 1, 1, 2),
  ('ফারজানা ইয়াসমিন, সিলেট', 'প্রথমে ভয় পাচ্ছিলাম অনলাইনে অর্ডার করতে। ওনারা ফোনে কনফার্ম করে পাঠিয়েছেন, ক্যাশ অন ডেলিভারিতে নিয়েছি। প্রোডাক্ট অরিজিনাল, কোনো সাইড ইফেক্ট হয়নি।', 5, 1, 1, 3),
  ('রুমানা পারভীন, রাজশাহী', 'দুর্গন্ধ আর চুলকানির সমস্যা ছিল দীর্ঘদিনের। ২ সপ্তাহেই পরিবর্তন বুঝতে পেরেছি। খাওয়ার নিয়ম ওনারা ফোনে সুন্দর করে বুঝিয়ে দিয়েছেন।', 4, 1, 0, 4),
  ('তানিয়া সুলতানা, খুলনা', 'শরীর খুব দুর্বল লাগত, খাবারে রুচি ছিল না। এই সাপ্লিমেন্ট খাওয়ার পর অনেকটা সুস্থ বোধ করছি। দামও সাধ্যের মধ্যে।', 5, 1, 0, 5);

-- FAQs
DELETE FROM faqs;
INSERT INTO faqs (question, answer, sort_order, is_visible) VALUES
  ('কতদিন সেবন করলে ফল পাব?', 'সাধারণত ৭ দিনের মধ্যেই কার্যকরী পরিবর্তন অনুভব করবেন। স্থায়ী সমাধানের জন্য ২/৩ সপ্তাহ নিয়মিত সেবন করুন। পুরনো ও জটিল সমস্যার ক্ষেত্রে ২-৩ মাসের ফুল কোর্স করার পরামর্শ দেওয়া হয়।', 1, 1),
  ('কোনো পার্শ্বপ্রতিক্রিয়া আছে কি?', 'না। এটি সম্পূর্ণ প্রাকৃতিক হারবাল উপাদানে জার্মান ফর্মুলায় তৈরি এবং BCSIR পরীক্ষিত — কোনো পার্শ্বপ্রতিক্রিয়া নেই। তবে গর্ভবতী অবস্থায় সেবনের আগে ডাক্তারের পরামর্শ নিন।', 2, 1),
  ('আমার গোপনীয়তা রক্ষা হবে তো?', 'অবশ্যই। আপনার তথ্য ১০০% গোপন রাখা হয় এবং সাদামাটা প্যাকেজিংয়ে ডেলিভারি দেওয়া হয় — ভেতরে কী আছে ডেলিভারি ম্যানও জানতে পারবে না।', 3, 1),
  ('পেমেন্ট কীভাবে করব?', 'আমরা ক্যাশ অন ডেলিভারি সাপোর্ট করি। অগ্রীম কোনো পেমেন্ট লাগবে না — পণ্য হাতে পেয়ে ডেলিভারি ম্যানকে টাকা দিবেন।', 4, 1),
  ('অর্ডার করার পর কতদিনে পণ্য পাব?', 'ঢাকার ভেতরে ২৪-৪৮ ঘণ্টা এবং ঢাকার বাইরে সাধারণত ২-৪ কার্যদিবসের মধ্যে পণ্য পৌঁছে যায়। ২ মাস বা তার বেশি কোর্স নিলে ডেলিভারি চার্জ ফ্রি!', 5, 1),
  ('খাওয়ার নিয়ম কী?', 'প্রতিদিন সকালে খালি পেটে ১টি এবং রাতে খাবারের ৩০ মিনিট পর ১টি করে ট্যাবলেট। সেবনকালে ঠান্ডা পানি ও অতিরিক্ত ঝাল-মিষ্টি খাবার এড়িয়ে চলুন। বিস্তারিত নিয়ম প্যাকেজের সাথে লেখা থাকবে।', 6, 1),
  ('কাজ না করলে টাকা ফেরত পাব?', 'হ্যাঁ। নিয়ম মেনে পূর্ণ কোর্স সেবনের পরও কার্যকরী ফল না পেলে আমাদের হটলাইনে যোগাযোগ করুন — টাকা ফেরতের ব্যবস্থা করা হবে।', 7, 1),
  ('ডাক্তারের পরামর্শ নিতে পারব?', 'অবশ্যই। অর্ডারের আগে বা পরে যেকোনো পরামর্শের জন্য আমাদের হটলাইনে কল করুন — আমাদের এক্সপার্ট টিম আপনাকে বিনামূল্যে পরামর্শ দেবে।', 8, 1);

